def _run_probe(fn):
    """decode byte-exact, verify hash, execute verbatim, return
    (rc, n_pass, n_total)."""
    npass_expect, sha_expect, *chunks = PROBES[fn]
    raw = base64.b64decode("".join(chunks))
    sha = hashlib.sha256(raw).hexdigest()
    if sha != sha_expect:
        return (99, 0, 0)
    g = {"__name__": f"v957_embed_{fn[:-3]}"}
    buf = io.StringIO()
    with contextlib.redirect_stdout(buf):
        exec(compile(raw, fn, "exec"), g)
        rc = g["main"]()
    passes = g.get("PASS", [])
    return (rc, sum(bool(x) for x in passes), len(passes))


def run():
    reset()
    import numpy as np
    import sympy as sp

    print("v957 -- CCC crossover kinematics dictionary (six probes"
          " embedded byte-exact + in-run recomputation)")

    # ------------------------------------------------------------------
    # S0/S1: the six probes, byte-exact and green as typed
    # ------------------------------------------------------------------
    for fn in PROBES:
        rc, np_, nt = _run_probe(fn)
        exp = PROBES[fn][0]
        check(f"probe {fn}: hash pinned, re-run green as typed "
              f"({np_}/{nt}, expected {exp}/{exp}, rc={rc})",
              int(rc == 0 and np_ == nt == exp), 1, exact=True)

    # ------------------------------------------------------------------
    # in-run recomputation (independent of the embedded sources)
    # ------------------------------------------------------------------
    RNG = np.random.default_rng(20260824)

    # (1) reciprocal structure
    zs = RNG.standard_normal(32) + 1j * RNG.standard_normal(32)
    check("tau(z) = -1/z satisfies Omega*tau(Omega) = -1 identically",
          int(all(np.isclose(z * (-1.0 / z), -1.0) for z in zs)), 1,
          exact=True)

    # (3) Stinespring: transport, isometry, exact contraction
    LAM2, LAM3 = (2.0 / 3.0) ** 6, (1.0 / 3.0) ** 6
    u2 = np.array([1.0, -1.0, 0.0]) / np.sqrt(2)
    u3 = np.array([1.0, 1.0, -2.0]) / np.sqrt(6)
    J = np.full((3, 3), 1.0 / 3.0)
    T = J + LAM2 * np.outer(u2, u2) + LAM3 * np.outer(u3, u3)
    kraus = [np.sqrt(T[i, j]) * np.outer(np.eye(3)[i], np.eye(3)[j])
             for i in range(3) for j in range(3)]
    V = np.zeros((27, 3))
    for a, K in enumerate(kraus):
        for i in range(3):
            V[i * 9 + a, :] += K[i, :]
    check("Stinespring V^dag V = 1_3 exactly (the v221 transport is a"
          " reduced channel of an isometry)",
          int(np.allclose(V.T @ V, np.eye(3))), 1, exact=True)
    ok_rate = all(np.isclose(
        np.linalg.norm(np.linalg.matrix_power(T, k) - J, 2), LAM2 ** k,
        rtol=1e-10) for k in range(1, 6))
    check("||T^n - P_star||_2 = (2/3)^{6n} exactly, n = 1..5",
          int(ok_rate), 1, exact=True)

    # (4) uplift core: Hopf identity + deck freeness + commutant
    vs = RNG.standard_normal((32, 2)) + 1j * RNG.standard_normal((32, 2))
    vs /= np.linalg.norm(vs, axis=1, keepdims=True)
    def hopf_stereo(v):
        w = 2 * v[0] * np.conj(v[1])
        h3 = abs(v[0]) ** 2 - abs(v[1]) ** 2
        return (w) / (1 - h3)
    check("stereographic(Hopf(v)) = z1/z2 exactly (the seam sphere IS"
          " the Hopf base)",
          int(all(np.isclose(hopf_stereo(v), v[0] / v[1]) for v in vs)),
          1, exact=True)
    DECK = np.diag([1j, -1j])
    free = all(not np.any(np.isclose(np.linalg.eigvals(
        np.linalg.matrix_power(DECK, k)), 1.0)) for k in (1, 2, 3))
    check("v492 deck acts freely on S^3 (lens crossover smooth)",
          int(free), 1, exact=True)

    def real_so4(M2):
        R = np.zeros((4, 4))
        for j in range(2):
            e = np.zeros(2, complex); e[j] = 1.0
            w = M2 @ e
            R[0, 2*j], R[1, 2*j], R[2, 2*j], R[3, 2*j] = (
                w[0].real, w[0].imag, w[1].real, w[1].imag)
            w = M2 @ (1j * e)
            R[0, 2*j+1], R[1, 2*j+1], R[2, 2*j+1], R[3, 2*j+1] = (
                w[0].real, w[0].imag, w[1].real, w[1].imag)
        return R

    def commutant_dims(g4s):
        basis, kind = [], []
        for a in range(4):
            for b in range(a + 1, 4):
                X = np.zeros((5, 5)); X[a, b], X[b, a] = 1., -1.
                basis.append(X); kind.append("rot")
        for a in range(4):
            X = np.zeros((5, 5)); X[a, 4], X[4, a] = 1., 1.
            basis.append(X); kind.append("boost")
        rows = []
        for g4 in g4s:
            g = np.eye(5); g[:4, :4] = g4
            gi = np.linalg.inv(g)
            rows.append(np.stack([((g @ B @ gi) - B).ravel()
                                  for B in basis], axis=1))
        A = np.vstack(rows)
        _, s, vt = np.linalg.svd(A)
        null = vt[np.sum(s > 1e-10):]
        boost = sum(abs(c[i]) for c in null
                    for i in range(10) if kind[i] == "boost")
        return null.shape[0], boost

    d_deck, b_deck = commutant_dims([real_so4(DECK)])
    d_ctrl, b_ctrl = commutant_dims([np.eye(4)])
    check("so(4,1) deck-commutant = 4 Killing fields with boost content"
          " 0 (Yamabe rigidity of the crossover); control S^3 keeps 10"
          " with 4 boosts",
          int(d_deck == 4 and b_deck < 1e-8 and d_ctrl == 10
              and b_ctrl > 1.0), 1, exact=True)

    # (5) KMS closure
    w, Vv = np.linalg.eigh(T)
    Hmod = Vv @ np.diag(-np.log(w)) @ Vv.T
    hev = np.sort(np.linalg.eigvalsh(Hmod))
    D2, D3 = 6 * np.log(1.5), 6 * np.log(3.0)
    check("spec(-ln T) = {0, 6 ln(3/2), 6 ln 3} exactly and"
          " T = e^{-H_mod} (one tick = one unit of KMS time)",
          int(np.allclose(hev, [0.0, D2, D3])
              and np.allclose(Vv @ np.diag(np.exp(-(-np.log(w)))) @ Vv.T,
                              T)), 1, exact=True)
    c3 = 1 / (8 * sp.pi)
    check("v526 normalisation replicated exactly: 1/(4 c3) = 2 pi ="
          " beta_angle (Gibbons-Hawking on the crossover fibre)",
          int(sp.simplify(1 / (4 * c3) - 2 * sp.pi) == 0), 1, exact=True)

    # (7) selector necessity core: D_4 closure only at delta = pi/2
    def adm_axes(delta):
        marks = np.array([0.0, np.pi, delta, delta + np.pi]) % (2*np.pi)
        cands = sorted({round(float((mi + mj) % (2*np.pi)), 12)
                        for mi in marks for mj in marks})
        n = 0
        for alpha in cands:
            img = (alpha - marks) % (2 * np.pi)
            if all(np.min(np.abs(((img[i] - marks + np.pi) % (2*np.pi))
                                 - np.pi)) < 1e-9 for i in range(4)):
                n += 1
        return n
    ok_generic = all(adm_axes(d) == 2 for d in (0.3, 0.9, 1.4, 2.2))
    check("M(delta) admissible reflections: V_4 (2 axes) generically,"
          " D_4 (4 axes) exactly at delta = pi/2 -- the clock"
          " factorisation exists only at mu_4",
          int(ok_generic and adm_axes(np.pi / 2) == 4), 1, exact=True)

    # (8) frozen kernel invariants
    check("frozen rate ratio ln3/ln(3/2) = 2.709511 (exact logs of"
          " 729/64 and 729)",
          float(D3 / D2), float(np.log(3) / np.log(1.5)), tol=1e-12)
    ETA_REC, ETA_0 = 280.3, 14165.0
    theta_deg = float(np.degrees(ETA_REC / (ETA_0 - ETA_REC)))
    check("frozen disc radius theta_max = eta_rec/(eta_0 - eta_rec) in"
          " [1.0, 1.3] deg (typed externals)",
          int(1.0 <= theta_deg <= 1.3), 1, exact=True)

    return summary("v957 CCC crossover kinematics dictionary")


if __name__ == "__main__":
    raise SystemExit(1 if run() else 0)
